null_data = {
    "a": [[1, None], [None], None, []],
    "b": [[1, 2], [1, 2], [1], []],
}


def test_contains_missing_item_with_nulls(
    request: pytest.FixtureRequest, constructor: Constructor
) -> None:
    if any(
        backend in str(constructor)
        for backend in ("dask", "modin", "cudf", "pyarrow", "pandas")
    ):
        request.applymarker(pytest.mark.xfail)
    result = nw.from_native(constructor(null_data)).select(
        nw.col("a").cast(nw.List(nw.Int32())).list.contains(2)
    )
    assert_equal_data(result, {"a": [False, False, None, False]})


def test_contains_none_expr(request: pytest.FixtureRequest, constructor: Constructor) -> None:
    if any(
        backend in str(constructor)
        for backend in ("dask", "modin", "cudf", "pyarrow", "pandas")
    ):
        request.applymarker(pytest.mark.xfail)
    result = nw.from_native(constructor(null_data)).select(
        nw.col("a").cast(nw.List(nw.Int32())).list.contains(None),
        nw.col("b").cast(nw.List(nw.Int32())).list.contains(None),
    )
    assert_equal_data(result, {"a": [True, True, None, False], "b": [False, False, False, False]})


def test_contains_none_series(
    request: pytest.FixtureRequest, constructor_eager: ConstructorEager
) -> None:
    if any(
        backend in str(constructor_eager)
        for backend in ("modin", "cudf", "pyarrow", "pandas")
    ):
        request.applymarker(pytest.mark.xfail)
    df = nw.from_native(constructor_eager(null_data), eager_only=True)
    result = df["a"].cast(nw.List(nw.Int32())).list.contains(None)
    assert_equal_data({"a": result}, {"a": [True, True, None, False]})


def test_contains_none_nested(request: pytest.FixtureRequest, constructor: Constructor) -> None:
    if any(
        backend in str(constructor)
        for backend in ("dask", "modin", "cudf", "pyarrow", "pandas")
    ):
        request.applymarker(pytest.mark.xfail)
    data_nested = {"a": [[[1], None], [[1]], None, []]}
    result = nw.from_native(constructor(data_nested)).select(
        nw.col("a").cast(nw.List(nw.List(nw.Int32()))).list.contains(None)
    )
    assert_equal_data(result, {"a": [True, False, None, False]})
